-- Shared celebration experience records. Requires wedding-projects and accepted team roles.
-- No personal records are published, no money is recorded, and no equipment is controlled.
begin;
create table if not exists public.cb_experience_items(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.cb_project_events on delete cascade,data jsonb not null,assignee uuid references auth.users,revision bigint not null default 1,created_by uuid not null references auth.users,updated_at timestamptz not null default now());
create index if not exists cb_experience_event on public.cb_experience_items(event_id);
create table if not exists public.cb_experience_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_experience_history(item_id uuid not null references public.cb_experience_items on delete cascade,revision bigint not null,actor_id uuid not null references auth.users,snapshot jsonb not null,at timestamptz not null default now(),primary key(item_id,revision));
alter table public.cb_experience_items enable row level security;alter table public.cb_experience_writes enable row level security;alter table public.cb_experience_history enable row level security;
revoke all on public.cb_experience_items,public.cb_experience_writes,public.cb_experience_history from public,anon,authenticated;
create or replace function public.cb_experience_member(p_event uuid,p_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.cb_project_events e join public.cb_projects p on p.id=e.project_id left join public.cb_members m on m.project_id=e.project_id and m.user_id=p_user where e.id=p_event and public.cb_collab_user_access(p_user,p.id,'read') and public.cb_collab_user_access(p_user,p.id,'events') and (p.owner_id=p_user or m.user_id is not null and (public.cb_collab_user_access(p_user,p.id,'write') or e.visibility='team' and m.role in ('family','bridal-party','sibling','friend') or exists(select 1 from public.cb_project_event_members em where em.event_id=e.id and em.user_id=p_user))))
$$;
create or replace function public.cb_experience_workspace(p_project uuid,p_event uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ev public.cb_project_events;begin
 if not coalesce(public.cb_project_access(p_project,'read'),false) then raise exception 'Wedding access required' using errcode='42501';end if;
 if p_event is not null then select * into ev from public.cb_project_events where id=p_event and project_id=p_project;if ev.id is null or not coalesce(public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Celebration access required' using errcode='42501';end if;end if;
 return jsonb_build_object('can_edit',public.cb_project_access(p_project,'write'),'finance',public.cb_project_access(p_project,'finance'),'events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'revision',e.revision,'date',e.details->>'date','time',e.details->>'time','venue',e.details->>'venue') order by e.details->>'date',e.title,e.id),'[]') from public.cb_project_events e where e.project_id=p_project and public.cb_experience_member(e.id,auth.uid())),'event',case when ev.id is null then null else jsonb_build_object('id',ev.id,'title',ev.title,'revision',ev.revision,'date',ev.details->>'date','time',ev.details->>'time','venue',ev.details->>'venue') end,'people',case when ev.id is null then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',coalesce(pr.full_name,'Wedding collaborator')) order by pr.full_name,x.id),'[]') from (select owner_id id from public.cb_projects where id=p_project union select user_id from public.cb_members where project_id=p_project) x left join public.cb_profiles pr on pr.user_id=x.id where public.cb_experience_member(ev.id,x.id)) end,'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'data',i.data,'assignee',i.assignee,'revision',i.revision) order by (i.data->>'order')::integer,i.data->>'time',i.data->>'title',i.id),'[]') from public.cb_experience_items i where i.event_id=ev.id));end;$$;
create or replace function public.cb_save_experience_item(p_event uuid,p_event_revision bigint,p_id uuid,p_revision bigint,p_client uuid,p_data jsonb,p_assignee uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare ev public.cb_project_events;i public.cb_experience_items;w public.cb_experience_writes;payload jsonb;result jsonb;k text;c jsonb;checks jsonb;begin
 select * into ev from public.cb_project_events where id=p_event;
 perform 1 from public.cb_projects where id=ev.project_id for update;
 select * into ev from public.cb_project_events where id=p_event for update;
 if ev.id is null or not coalesce(public.cb_project_access(ev.project_id,'write') and public.cb_experience_member(ev.id,auth.uid()),false) then raise exception 'Celebration planning access required' using errcode='42501';end if;
 payload=jsonb_build_object('event',p_event,'event_revision',p_event_revision,'id',p_id,'revision',p_revision,'data',p_data,'assignee',p_assignee);
 if p_client is null then raise exception 'Request ID required';end if;select * into w from public.cb_experience_writes where user_id=auth.uid() and client=p_client;if found then if w.payload is distinct from payload then raise exception 'Retry the original experience details' using errcode='PT409';end if;return w.response;end if;
 if ev.revision is distinct from p_event_revision then raise exception 'This celebration changed. Refresh its date and details before saving.' using errcode='PT409';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or p_data-array['title','section','status','brief','specifications','supplier','quantity','unit','time','order','url','checks']::text[]<>'{}' then raise exception 'Review experience fields';end if;
 foreach k in array array['title','section','status','brief','specifications','supplier','unit','time','url'] loop if jsonb_typeof(p_data->k) is distinct from 'string' or length(p_data->>k)>(case when k in ('brief','specifications') then 4000 when k='url' then 2000 else 200 end) then raise exception 'Review experience text limits';end if;end loop;
 if length(btrim(p_data->>'title'))=0 or p_data->>'section' not in ('food','drinks','cake','music','hosting','entertainment','screens','production','activities','moments','program','hospitality','vendors','inspiration','live','archive') or p_data->>'status' not in ('Planned','In progress','Ready','Complete','Cancelled') then raise exception 'Choose an experience title, category and status';end if;
 if jsonb_typeof(p_data->'quantity') is distinct from 'number' or (p_data->>'quantity')::numeric not between 0 and 1000000 or jsonb_typeof(p_data->'order') is distinct from 'number' or (p_data->>'order')::numeric not between 0 and 10000 or (p_data->>'order')::numeric<>trunc((p_data->>'order')::numeric) then raise exception 'Use a valid quantity and whole-number sequence';end if;
 if p_data->>'time'<>'' and p_data->>'time'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Use a valid local cue time';end if;
 if p_data->>'url'<>'' and (p_data->>'url'!~'^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$' or p_data->>'url'~'[<>]') then raise exception 'Use a public HTTPS reference';end if;
 checks=p_data->'checks';if jsonb_typeof(checks) is distinct from 'array' or jsonb_array_length(checks)>40 then raise exception 'Use up to 40 readiness checks';end if;
 for c in select value from jsonb_array_elements(checks) loop if jsonb_typeof(c) is distinct from 'object' or c-array['title','done']::text[]<>'{}' or jsonb_typeof(c->'title') is distinct from 'string' or length(btrim(c->>'title')) not between 1 and 200 or jsonb_typeof(c->'done') is distinct from 'boolean' then raise exception 'Review readiness check details';end if;end loop;
 if exists(select 1 from jsonb_array_elements(checks) ck group by ck.value->>'title' having count(*)>1) then raise exception 'Use distinct readiness action titles';end if;
 if p_data->>'status' in ('Ready','Complete') and exists(select 1 from jsonb_array_elements(checks) ck where not (ck.value->>'done')::boolean) then raise exception 'Finish readiness checks before marking ready or complete';end if;
 if p_assignee is not null and not public.cb_experience_member(ev.id,p_assignee) then raise exception 'Choose an accepted collaborator with celebration access';end if;
 if p_id is null then if p_revision is distinct from 0::bigint then raise exception 'Refresh before creating an experience item' using errcode='PT409';end if;if (select count(*) from public.cb_experience_items where event_id=p_event)>=3000 then raise exception 'Celebration record allowance reached';end if;
 insert into public.cb_experience_items(event_id,data,assignee,created_by) values(p_event,p_data,p_assignee,auth.uid()) returning * into i;
 else select * into i from public.cb_experience_items where id=p_id and event_id=p_event for update;if i.id is null then raise exception 'Choose a record in this celebration' using errcode='42501';end if;if i.revision is distinct from p_revision then raise exception 'Another teammate changed this record. Your edits remain in the form. Copy them before refreshing.' using errcode='PT409';end if;
 update public.cb_experience_items set data=p_data,assignee=p_assignee,revision=revision+1,updated_at=now() where id=p_id returning * into i;end if;
 result=jsonb_build_object('id',i.id,'data',i.data,'assignee',i.assignee,'revision',i.revision);insert into public.cb_experience_history values(i.id,i.revision,auth.uid(),to_jsonb(i),now());insert into public.cb_experience_writes values(auth.uid(),p_client,payload,result);return result;
end;$$;
revoke all on function public.cb_experience_member(uuid,uuid),public.cb_experience_workspace(uuid,uuid),public.cb_save_experience_item(uuid,bigint,uuid,bigint,uuid,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.cb_experience_workspace(uuid,uuid),public.cb_save_experience_item(uuid,bigint,uuid,bigint,uuid,jsonb,uuid) to authenticated;
notify pgrst,'reload schema';
commit;
